UPDATE email_templates SET subject = 'We received your availability: {{time}}', text_body = 'Hi {{name}},\n\nThanks for sharing your availability. Your preferred time is with us, and the organizer will review it shortly.\n\nYou are all set for now. We will be in touch when the meeting is confirmed.' WHERE template_key = 'received' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'Your meeting is confirmed: {{time}}', text_body = 'Hi {{name}},\n\nGreat news, your meeting is confirmed. Everything you need is below, and a calendar invitation is attached for you.' WHERE template_key = 'meeting_details' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'A friendly reminder for {{time}}', text_body = 'Hi {{name}},\n\nJust a friendly reminder that your meeting is coming up. We are looking forward to speaking with you. Your calendar invitation is attached again for convenience.' WHERE template_key = 'reminder' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'We missed you at the meeting', text_body = 'Hi {{name}},\n\nWe missed you at the meeting and hope everything is okay. Do not worry, plans change. Contact the organizer and we will help find another time that works for you.' WHERE template_key = 'missed' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'Let''s find a better meeting time', text_body = 'Hi {{name}},\n\nWe need to move the meeting, but finding another time is easy. Use the button below to choose a slot that works better for you.' WHERE template_key = 'reschedule' AND updated_by IS NULL;
UPDATE email_templates SET subject = 'Meeting cancelled: {{time}}', text_body = 'Hi {{name}},\n\nThe planned meeting has been cancelled. We are sorry for the change. Contact the organizer whenever you are ready if you would like to plan another conversation.' WHERE template_key = 'cancelled' AND updated_by IS NULL;
